    const user = await requireUser();
    const { id } = await ctx.params;
    const view = await getSessionView(user.id, id);
    if (!view) return jsonError('NOT_FOUND', 'Cooking session not found');
    return jsonOk(view);
  } catch (err) {
    return handleRouteError(err);
  }
}

